type ExaClient struct{ client *NativeClient }

func NewExaClient(o NativeOptions) (*ExaClient, error) {
	c, e := NewNativeClient("exa", o)
	if e != nil {
		return nil, e
	}
	return &ExaClient{client: c}, nil
}
func (c *ExaClient) Operations() []Operation { return c.client.Operations() }
func (c *ExaClient) Call(ctx context.Context, name string, input NativeInput) (NativeResult, error) {
	return c.client.Call(ctx, name, input)
}
